const fs = require("fs");
const path = "server/app.rb";
const data = fs.readFileSync(path, "utf8");
const idx = data.indexOf('key.include?("');
if (idx === -1) { console.error("marker not found"); process.exit(1); }
const closeIdx = data.indexOf('")', idx + 'key.include?("'.length);
const inner = data.slice(idx + 'key.include?("'.length, closeIdx);
console.log("inner char codes:", Array.from(inner).map(c => c.codePointAt(0)));
const fixed = data.slice(0, idx) + 'key.include?("\\u0000")' + data.slice(closeIdx + 2);
fs.writeFileSync(path, fixed, "utf8");
console.log("done");

